window.TP3B["camara:220666"] = [{"t":"PL","n":"5441","y":"2026","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para dispor que a pena do crime de denunciação caluniosa será a mesma cominada ao crime imputado","d":"2026-09-22","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-09-22","ds":"Apresentação do PL n. 5441/2026 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para dispor que a pena do crime de denunciação caluniosa será a mesma cominada ao crime imputado\".","id":"2646922","law":false,"r":"m"},{"t":"PL","n":"5432","y":"2026","e":"Altera a Lei nº 8.171, de 17 de janeiro de 1991, para estabelecer diretrizes de tratamento diferenciado na cobrança pela emissão da Guia de Trânsito Animal para aves das ordens Passeriformes e Psittaciformes.","d":"2026-09-22","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-09-22","ds":"Apresentação do PL n. 5432/2026 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Altera a Lei nº 8.171, de 17 de janeiro de 1991, para estabelecer diretrizes de tratamento diferenciado na cobrança pela emissão da Guia de Trânsito Animal para aves das ordens Passeriformes e Psittaciformes\".","id":"2646899","law":false,"r":"m"},{"t":"PL","n":"5232","y":"2026","e":"Altera a Lei nº 9.503, de 23 de setembro de 1997 (Código de Trânsito Brasileiro), para estabelecer garantias na classificação de danos em veículos envolvidos em sinistros de trânsito e na imposição de restrições administrativas.","d":"2026-08-31","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-08-31","ds":"Apresentação do PL n. 5232/2026 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Altera a Lei nº 9.503, de 23 de setembro de 1997 (Código de Trânsito Brasileiro), para estabelecer garantias na classificação de danos em veículos envolvidos em sinistros de trânsito e na imposição de restrições administrativas\".","id":"2644973","law":false,"r":"m"},{"t":"PL","n":"5154","y":"2026","e":"Institui o Dia Nacional do Provedor Regional de Internet.","d":"2026-08-24","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-08-24","ds":"Apresentação do PL n. 5154/2026 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Institui o Dia Nacional do Provedor Regional de Internet\".","id":"2644372","law":false,"r":"m"},{"t":"PL","n":"5150","y":"2026","e":"Altera a Lei nº 10.826, de 22 de dezembro de 2003 – Estatuto do Desarmamento, para autorizar o porte de arma aos Auditores Fiscais Federais Agropecuários.","d":"2026-08-24","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-08-24","ds":"Apresentação do PL n. 5150/2026 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Altera a Lei nº 10.826, de 22 de dezembro de 2003 – Estatuto do Desarmamento, para autorizar o porte de arma aos Auditores Fiscais Federais Agropecuários\".","id":"2644364","law":false,"r":"m"},{"t":"PL","n":"4959","y":"2026","e":"Altera a Lei nº 13.675, de 11 de junho de 2018, para aperfeiçoar o monitoramento da vitimização e da saúde ocupacional dos profissionais de segurança pública e defesa social e instituir o Procedimento de Avaliação e Aprendizagem Pós-Evento Crítico","d":"2026-08-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Proposição","u":"2026-08-10","ds":"Apresentação do PL n. 4959/2026 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Altera a Lei nº 13.675, de 11 de junho de 2018, para aperfeiçoar o monitoramento da vitimização e da saúde ocupacional dos profissionais de segurança pública e defesa social e instituir o Procedimento de Avaliação e Aprendizagem Pós-Evento Crítico\".","id":"2642386","law":false,"r":"m"},{"t":"PL","n":"4958","y":"2026","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 — Código Penal, para tipificar os crimes de coação coletiva violenta e de obstrução coercitiva de via, e as Leis nº 8.072, de 25 de julho de 1990, e 15.358, de 24 de março de 2026.","d":"2026-08-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Proposição","u":"2026-08-10","ds":"Apresentação do PL n. 4958/2026 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 — Código Penal, para tipificar os crimes de coação coletiva violenta e de obstrução coercitiva de via, e as Leis nº 8.072, de 25 de julho de 1990, e 15.358, de 24 de março de 2026\".","id":"2642384","law":false,"r":"m"},{"t":"PLP","n":"230","y":"2026","e":"Altera a Lei Complementar nº 213, de 15 de janeiro de 2025, e o Decreto-Lei nº 73, de 21 de novembro de 1966, a Lei nº 10.190, de 14 de fevereiro de 2001, a Lei Complementar nº 126, de 15 de janeiro de 2007, e a Lei nº 12.249, de 11 de junho de 2010, para instituir regime jurídico próprio, proporcional e autogerido para as associações de proteção patrimonial mutualista, e dá outras providências.","d":"2026-08-05","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Recebimento - Relator(a)","u":"2026-08-12","ds":"Apresentação do PRLE n. 1 PLEN (Parecer Preliminar às Emendas de Plenário), pela Deputada Maria Rosas (REPUBLIC/SP).","id":"2641972","law":false,"r":"m"},{"t":"PL","n":"4729","y":"2026","e":"Altera o art. 233-A da Lei nº 4.737, de 15 de julho de 1965 (Código Eleitoral), para reduzir o prazo de habilitação ao voto em trânsito dos integrantes das Forças Armadas, dos agentes de segurança pública de que trata o art. 144 da Constituição Federal e das guardas municipais em serviço no dia da eleição, para impor à Justiça Eleitoral o dever de organizar a votação desses eleitores, para assegurar a dispensa remunerada de até duas horas de serviço para o exercício do voto e para instituir sanção pelo descumprimento.","d":"2026-07-20","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2026-07-20","ds":"Apresentação do PL n. 4729/2026 (Projeto de Lei), pelos Deputados Sargento Portugal (PODE/RJ) e Coronel Meira PL        , que \"Altera o art. 233-A da Lei nº 4.737, de 15 de julho de 1965 (Código Eleitoral), para reduzir o prazo de habilitação ao voto em trânsito dos integrantes das Forças Armadas, dos agentes de segurança pública de que trata o art. 144 da Constituição Federal e das guardas munici","id":"2641424","law":false,"r":"c"},{"t":"PDL","n":"849","y":"2026","e":"Susta, em sua integralidade, os efeitos da Resolução nº 491, de 4 de maio de 2026, do Conselho Nacional de Seguros Privados - CNSP, que estabelece as normas gerais aplicáveis às operações de proteção patrimonial mutualista.","d":"2026-07-14","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2026-07-14","ds":"Apresentação do PDL n. 849/2026 (Projeto de Decreto Legislativo de Sustação de Atos Normativos do Poder Executivo), pelo Deputado Coronel Meira (PL/PE), que \"Susta, em sua integralidade, os efeitos da Resolução nº 491, de 4 de maio de 2026, do Conselho Nacional de Seguros Privados - CNSP, que estabelece as normas gerais aplicáveis às operações de proteção patrimonial mutualista\".","id":"2639521","law":false,"r":"m"},{"t":"PL","n":"2902","y":"2026","e":"Altera a redação da Lei nº 13.260, de 16 de março de 2016.","d":"2026-06-08","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-08-19","ds":"Recebimento pelo(a) CCJC.","id":"2630222","law":false,"r":"c"},{"t":"PL","n":"2576","y":"2026","e":"Dispõe sobre a obrigatoriedade de instalação de pontos de ancoragem e sistemas permanentes de proteção contra quedas em edificações destinadas à instalação, manutenção e reparo de sistemas de climatização e refrigeração em altura.","d":"2026-05-25","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-07-10","ds":"Recebimento pelo(a) CDU.","id":"2627427","law":false,"r":"m"},{"t":"PL","n":"1972","y":"2026","e":"Declara a celebração da missa segundo o rito romano na forma extraordinária, também conhecida como Missa Tridentina, como Patrimônio Cultural e Imaterial Brasileiro.","d":"2026-04-24","o":"in_progress","s":"Aguardando Parecer","tr":"Abertura de Prazo","u":"2026-09-11","ds":"Prazo para Emendas ao Projeto (5 sessões a partir de 14/09/2026)","id":"2618360","law":false,"r":"m"},{"t":"PL","n":"1728","y":"2026","e":"Institui o Dia Nacional dos Policiais e Bombeiros Militares Veteranos.","d":"2026-04-09","o":"in_progress","s":"Aguardando Parecer","tr":"Abertura de Prazo","u":"2026-09-11","ds":"Prazo para Emendas ao Projeto (5 sessões a partir de 14/09/2026)","id":"2614904","law":false,"r":"m"},{"t":"PL","n":"1424","y":"2026","e":"Define antissemitismo com a finalidade de instruir as políticas públicas nacionais.","d":"2026-03-26","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificações","u":"2026-05-25","ds":"Deferidos os Requerimentos n. 1733/2026;  1734/2026; 1738/2026; 1739/2026; 1749/2026; 1750/2026; 1762/2026; 1784/2026 e 1810/2026.","id":"2612333","law":false,"r":"c"},{"t":"PDL","n":"1031","y":"2025","e":"Susta os efeitos da Resolução CONTRAN Nº 1.020 de 01 dezembro de 2025, emitida pelo Conselho Nacional de Trânsito – CONTRAN, que normatiza os procedimentos sobre a aprendizagem, habilitação e expedição de documentos de condutores e o processo de formação do candidato à da Carteira Nacional de Habilitação ou Autorização para Conduzir Ciclomotor.","d":"2025-12-01","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Notificação - Pasta genérica","u":"2026-03-11","ds":"Deferidos  os Requerimentos 5229. 5242, 5245 e 5281, todos de 2025.","id":"2589598","law":false,"r":"m"},{"t":"PEC","n":"40","y":"2025","e":"Altera o Art. 7° da Constituição Federal para prever a possibilidade de opção pelos empregados quanto à jornada de trabalho, podendo escolher entre o regime comum previsto pela Consolidação das Leis do Trabalho (CLT), ou um regime flexível baseado em horas trabalhadas.","d":"2025-10-29","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2026-02-25","ds":"Apresentação do REQ n. 3/2026 (Requerimento de Audiência Pública), pelo Deputado Domingos Sávio (PL/MG), que \"Requer realização de audiência pública acerca da redução da jornada de trabalho, conforme proposta nas PECs nº 40/2025 e nº 8/2025\".","id":"2578996","law":false,"r":"c"},{"t":"PL","n":"5434","y":"2025","e":"Institui o Programa Nacional de Reconhecimento e Mérito Operacional das Forças de Segurança Pública, destinado a valorizar e incentivar atos de bravura, eficiência, excelência técnica e dedicação exemplar no combate à criminalidade e na proteção da sociedade, e dá outras providências.","d":"2025-10-28","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2026-02-02","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 03/02/2026.","id":"2577282","law":false,"r":"c"},{"t":"PDL","n":"800","y":"2025","e":"Susta os efeitos da Consulta Pública Processo: 50000.034372/2025-74 de 02/10/2025, emitida pela Secretaria de Nacional de Trânsito – SENATRAN, que trata de Minuta de Resolução que “normatiza os procedimentos sobre a aprendizagem, habilitação e expedição de documentos de condutores e o processo de formação do candidato à obtenção da Carteira Nacional de Habilitação ou da Autorização para Conduzir Ciclomotor”.","d":"2025-10-07","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Notificações","u":"2025-11-06","ds":"Deferido o REQ 4532/2025.","id":"2567768","law":false,"r":"m"},{"t":"PEC","n":"32","y":"2025","e":"Esta Lei altera o artigo 5º, inciso XLIII, da Constituição Federal, o qual prevê que nos casos de crimes previstos neste inciso, a pena deverá ser cumprida integralmente em regime fechado, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem, e dá outras providências.","d":"2025-08-20","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Aprovação de Requerimento","u":"2026-09-01","ds":"Aprovado o requerimento nº 1/2026,da Sra. Talíria Petrone que requer a realização de Audiência Pública no âmbito da Comissão Especial sobre a redução da maioridade penal (PEC 32/2015) para debater a idade penal como cláusula pétrea e o controle de constitucionalidade da redução frente aos direitos e garantias individuais imutáveis da Constituição de 1988, sugerindo os seguintes especialistas: Dr. ","id":"2551011","law":false,"r":"c"},{"t":"PEC","n":"30","y":"2025","e":"Altera a Constituição Federal e o Ato das Disposições Constitucionais Transitórias para estabelecer regras antiprivilégios para agentes públicos.","d":"2025-08-12","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2025-11-19","ds":"Apresentação do REQ n. 4996/2025 (Requerimento de Inclusão ou Retirada de Assinatura em Proposição de Iniciativa Coletiva Obrigatória), pelo Deputado Sargento Portugal (PODE/RJ), que \"Solicita a retirada de apoiamento à Proposta de Emenda à Constituição (PEC) nº 30/2025. \".","id":"2543145","law":false,"r":"c"},{"t":"PL","n":"3462","y":"2025","e":"Altera a Lei º 9.503, de 23 de setembro de 1997 - Código de Trânsito Brasileiro, para vedar a exigência de quitação de débitos tributários ou veiculares não vinculados ao prontuário do condutor como condição para a renovação da Carteira Nacional de Habilitação (CNH).","d":"2025-07-16","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-07-01","ds":"Designado Relator, Dep. Geraldo Mendes (UNIÃO-PR).","id":"2537280","law":false,"r":"m"},{"t":"PL","n":"3325","y":"2025","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 – Código Penal, e a Lei nº 8.072, de 25 de julho de 1990 – Lei de Crimes Hediondos, para dispor sobre crimes de furto, roubo e receptação de dispositivo móvel de comunicação e dá outras providências.","d":"2025-07-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-03-17","ds":"Apensação do PL 6545/2025 a esta proposição.","id":"2534151","law":false,"r":"m"},{"t":"PDL","n":"228","y":"2025","e":"Susta, nos termos do art. 49, V, da Constituição Federal, os efeitos do Decreto nº 12.467, de 23 de maio de 2025.","d":"2025-05-26","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados","tr":"Apresentação de Requerimento","u":"2025-06-25","ds":"Apresentação do REQ n. 2398/2025 (Requerimento de Apensação), pelo Deputado Zucco (PL/RS), que \"Requer a apensação dos projetos que especifica ao Projeto de Decreto Legislativo n. 214/2025\".","id":"2516046","law":false,"r":"c"},{"t":"PL","n":"2265","y":"2025","e":"Revoga os arts. 359-L e 359-M do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 – Código Penal Brasileiro.","d":"2025-05-13","o":"approved_with_another_bill","s":"Arquivada","tr":"Prejudicialidade (Plenário)","u":"2025-12-09","ds":"Matéria aprovada na forma do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão). Esta proposição fica prejudicada, na forma do art. 191 do RICD.","id":"2508216","law":false,"r":"c"},{"t":"PDL","n":"179","y":"2025","e":"Susta os efeitos da Resolução nº 163, de 13 de março de 2014, do Conselho Nacional dos Direitos da Criança e do Adolescente - CONANDA, que dispõe sobre a abusividade do direcionamento de publicidade e de comunicação mercadológica à criança e ao adolescente.","d":"2025-05-08","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-04-17","ds":"Designado Relator, Dep. Clodoaldo Magalhães (PV-PE).","id":"2506909","law":false,"r":"m"},{"t":"PL","n":"1952","y":"2025","e":"Dispõe sobre a obrigatoriedade do uso exclusivo das cores da bandeira nacional nos uniformes de seleções e equipes esportivas que representem oficialmente o Brasil em competições internacionais e dá outras providências.","d":"2025-04-29","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-10-03","ds":"Recebimento pela CCJC, apensado ao PL-1928/2025","id":"2502339","law":false,"r":"m"},{"t":"PEC","n":"17","y":"2025","e":"Acrescenta os §§ 11, 12 e 13 ao art. 144 da Constituição Federal, para instituir o piso salarial dos servidores policiais civis e militares e bombeiros militares.","d":"2025-04-23","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2025-04-23","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2499794","law":false,"r":"m"},{"t":"PL","n":"1688","y":"2025","e":"Dispõe sobre o reconhecimento jurídico dos Oficiais de Justiça como categoria profissional de natureza específica, vinculada ao exercício de atividade estratégica e estruturante da função jurisdicional do Estado, e estabelece outras providências correlatas.","d":"2025-04-14","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2025-04-14","ds":"Apresentação do PL n. 1688/2025 (Projeto de Lei), pelo Deputado Coronel Meira (PL/PE), que \"Dispõe sobre o reconhecimento jurídico dos Oficiais de Justiça como categoria profissional de natureza específica, vinculada ao exercício de atividade estratégica e estruturante da função jurisdicional do Estado, e estabelece outras providências correlatas.\n\n\".","id":"2497757","law":false,"r":"m"},{"t":"PLP","n":"81","y":"2025","e":"Altera a Lei Complementar nº 214, de 16 de janeiro de 2025, para modificar regras relativas ao regime diferenciado do Imposto sobre Bens e Serviços (IBS) e da Contribuição Social sobre Bens e Serviços (CBS) aplicável aos automóveis de passageiros adquiridos por pessoas com deficiência ou com transtorno do espectro autista.","d":"2025-04-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2026-03-20","ds":"Devolvida pelo Relator sem Manifestação.","id":"2494797","law":false,"r":"c"},{"t":"PL","n":"1493","y":"2025","e":"Altera o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), e a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para vedar o uso de monitoração eletrônica em determinadas hipóteses e dá outras providências.","d":"2025-04-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-05-28","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 29/05/2025 PAG 617","id":"2494572","law":false,"r":"m"},{"t":"PL","n":"1463","y":"2025","e":"Dispõe sobre a obrigatoriedade de disponibilização de medicamentos para o tratamento da obesidade no Sistema Único de Saúde (SUS) e estabelece diretrizes para políticas públicas voltadas ao tratamento da obesidade e doenças associadas, com especial atenção ao lipedema.","d":"2025-04-02","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-05-28","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 29/05/2025 PAG 504","id":"2494398","law":false,"r":"m"},{"t":"PL","n":"1433","y":"2025","e":"Dispõe sobre o reconhecimento dos Oficiais de Justiça como categoria profissional diferenciada e essencial à prestação jurisdicional, e dá outras providências.","d":"2025-04-02","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2025-06-16","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 17/06/2025.","id":"2494095","law":false,"r":"m"},{"t":"PL","n":"844","y":"2025","e":"Assegura às mulheres presas em decorrência dos atos do dia 8 de janeiro de 2023 a garantia a assistência médica e psicológica e dá outras providências.","d":"2025-03-11","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-18","ds":"Designada Relatora, Dep. Talíria Petrone (PSOL-RJ).","id":"2486278","law":false,"r":"m"},{"t":"PLP","n":"52","y":"2025","e":"Dispõe sobre diretrizes gerais para a fixação da base de cálculo do Imposto sobre a Propriedade de Veículos Automotores (IPVA) pelos Estados e pelo Distrito Federal e dá outras providências.","d":"2025-02-27","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-06-17","ds":"Designado Relator, Dep. Zé Trovão (PL-SC).","id":"2485811","law":false,"r":"m"},{"t":"PL","n":"724","y":"2025","e":"Introduz o crime de narcoterrorismo na Lei nº 13.260, de 16 de março de 2016.","d":"2025-02-27","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-03-17","ds":"Apensação do PL 196/2026 a esta proposição.","id":"2485763","law":false,"r":"m"},{"t":"PEC","n":"9","y":"2025","e":"Acrescenta o § 16 ao art. 198 da Constituição Federal, para dispor sobre as diretrizes para os Planos de Carreira e os pisos salariais nacionais dos profissionais de saúde do Sistema Único de Saúde.","d":"2025-02-27","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-06-10","ds":"Designado Relator, Dep. Coronel Assis (PL-MT).","id":"2485767","law":false,"r":"c"},{"t":"PLP","n":"10","y":"2025","e":"Estabelece diretrizes gerais para a fixação da alíquota do Imposto sobre a Propriedade de Veículos Automotores (IPVA) incidente sobre veículos automotores terrestres classificados como sinistrados recuperáveis e dá outras providências.","d":"2025-02-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-07-09","ds":"Encaminhada à publicação. Parecer da Comissão de Viação e Transportes Publicado em avulso e no DCD de 10/07/2026, Letra A.","id":"2482522","law":false,"r":"m"},{"t":"PDL","n":"26","y":"2025","e":"Susta a Instrução Normativa da Receita Federal do Brasil n.º 2.219, de 17 de setembro de 2024, que “dispõe sobre a obrigatoriedade de prestação de informações relativas às operações financeiras de interesse da Secretaria Especial da Receita Federal do Brasil na e-Financeira.”","d":"2025-02-03","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2025-03-20","ds":"Arquivado","id":"2482262","law":false,"r":"c"},{"t":"PEC","n":"51","y":"2024","e":"Altera o art. 7º e o Ato das Disposições Constitucionais Transitórias da Constituição Federal de 1988, para dispor sobre as condições especiais de trabalho do motorista profissional empregado no transporte rodoviário de cargas e de passageiros.","d":"2024-12-12","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Publicação de Proposição","u":"2025-11-13","ds":"Encaminhada à publicação. Parecer da Comissão de Constituição e Justiça e de Cidadania Publicado em avulso e no DCD de 14/11/2025, Letra A.","id":"2479738","law":false,"r":"c"},{"t":"PL","n":"4495","y":"2024","e":"Altera a Lei nº 11.343, de 23 de agosto de 2006, para equiparar ao crime de tráfico de drogas o tráfico de produtos fumígenos e outros derivados de tabacos que forem contrabandeados, pirateados, falsificados, corrompidos ou adulterados sem autorização e registros da ANVISA e da Receita Federal, independentemente da sua quantidade, e dá outras providências.","d":"2024-11-24","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-03-04","ds":"Encaminhada à publicação. Parecer da Comissão de Segurança Pública e Combate ao Crime Organizado Publicado em avulso e no DCD de 05/03/2026 PÁG 1161, Letra A.","id":"2471174","law":false,"r":"m"},{"t":"PL","n":"3896","y":"2024","e":"Estabelece normas para a prevenção e combate à violência política contra pessoas com deficiência, incluindo aquelas com Transtorno do Espectro Autista (TEA).","d":"2024-10-10","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-04-06","ds":"O Relator, Dep. Marangoni, deixou de ser membro da Comissão","id":"2462059","law":false,"r":"m"},{"t":"PEC","n":"28","y":"2024","e":"Acrescenta o art. 97-A e §§4º e 5º da Constituição Federal de 1988, para estabelecer o julgamento de referendo de liminares pelo colegiado de Tribunal, bem como criar hipótese de sustação de decisão do Supremo Tribunal Federal.","d":"2024-07-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-10-09","ds":"Aprovado o Parecer, com o seguinte resultado:  38 votos \"Sim\", 12 votos \"Não\". Quórum de votação: 50 votos.","id":"2448732","law":false,"r":"c"},{"t":"PL","n":"2786","y":"2024","e":"Institui o Dia Nacional dos Presos Políticos.","d":"2024-07-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificações","u":"2024-10-16","ds":"Deferido o Requerimento nº 3819/2024.","id":"2447559","law":false,"r":"m"},{"t":"PDL","n":"320","y":"2024","e":"Susta a Portaria nº 648, de 28 de maio de 2024, do Ministério da Justiça e Segurança Pública, que estabelece diretrizes sobre o uso de câmeras corporais pelos órgãos de segurança pública.","d":"2024-07-05","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-08-19","ds":"Recebimento pela CCJC, apensado ao PDL-295/2024","id":"2446998","law":false,"r":"m"},{"t":"PEC","n":"24","y":"2024","e":"Altera os §§ 4º, 4°-B e 7º do art. 40 da Constituição Federal e os artigos 5º, 10, 23, 24 e 26 da Emenda Constitucional nº 103, de 2019, acrescenta o art. 144-A a Constituição e dá outras providências.","d":"2024-06-24","o":"in_progress","s":"Aguardando Constituição de Comissão Temporária","tr":"Expedição de Documento","u":"2026-08-26","ds":"Ato da Presidência: Cria Comissão Especial, nos termos do § 2º do art. 202 do Regimento Interno. Publicado em DCD Extra no dia 26/08/2026.","id":"2442880","law":false,"r":"c"},{"t":"PL","n":"2499","y":"2024","e":"Dispõe sobre a obrigatoriedade da notificação à autoridade policial, pelos hospitais, clínicas e unidades básicas de saúde, da interrupção de gestação decorrente de estupro e dá outras providências.","d":"2024-06-19","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2024-09-18","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 30/08/2024 a 18/09/2024). Não foram apresentadas emendas.","id":"2442393","law":false,"r":"m"},{"t":"PL","n":"2388","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) e a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para estabelecer punições mais severas aos crimes de estupro e estupro de vulnerável.","d":"2024-06-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-05-26","ds":"Apense-se a este o PL 1682/2026","id":"2440784","law":false,"r":"c"},{"t":"PDL","n":"301","y":"2024","e":"Susta o Decreto nº 12.032, de 28 de maio de 2024, que exclui a Empresa Gestora de Ativos S. A. - Emgea do Programa Nacional de Desestatização e revoga sua qualificação no âmbito do Programa de Parcerias e Investimentos da Presidência da República.","d":"2024-06-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-08-11","ds":"Recebimento pela CCJC, apensado ao PDL-299/2024","id":"2437509","law":false,"r":"c"},{"t":"PL","n":"2058","y":"2024","e":"Cria a Lei de Criminalização do Revenge Porn e Sextorsão.","d":"2024-05-27","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-10-08","ds":"Recebimento pela CCJC.","id":"2436529","law":false,"r":"c"},{"t":"PDL","n":"275","y":"2024","e":"Susta a Portaria nº 224 - COLOG/C EX, de 17 de maio de 2024, que altera as normas para aquisição, registro, cadastro e transferência de armas de fogo e a aquisição de munições, insumos, acessórios e outros produtos controlados de competência do Comando do Exército, aprovadas pela Portaria nº 167 - COLOG/CEx, de 22 de janeiro de 2024.","d":"2024-05-21","o":"status_not_published","s":"","tr":"Notificacao para Publicação Intermediária","u":"2026-03-18","ds":"Designado Relator, Dep. Ricardo Salles (NOVO-SP), para o PDL 272/2024, ao qual esta proposição está apensada.","id":"2434946","law":false,"r":"m"},{"t":"PL","n":"1633","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal para considerar como crime a criação de óbice ou embaraço fiscal, sanitário, ambiental ou administrativo, oimpedimento ou dificuldade ao serviço de combate ao perigo, de socorro ou salvamento, ou a entregade donativos ou o resgate às vítimas, durante a vigência de estado de calamidade pública.","d":"2024-05-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2024-05-13","ds":"Recebimento pela CCJC.","id":"2431790","law":false,"r":"m"},{"t":"PL","n":"1571","y":"2024","e":"Institui o programa emergencial de incentivo a donativos e voluntariado para situações de emergência e calamidade pública, altera as leis n. 6.437, de 20 de agosto de 1977, 8.137, de 27 de dezembro de 1990,  8.234, de 17 de setembro de 1991, 9.537, de 11 de dezembro de 1997 e dá outras providências.","d":"2024-05-06","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-12-08","ds":"Recebimento pela CFT, com as proposições PL-1577/2024, PL-1718/2024 apensadas.","id":"2431054","law":false,"r":"c"},{"t":"PL","n":"1565","y":"2024","e":"Dispõe sobre a suspensão de exigências de pagamentos de tributos federais, durante o período de dois anos, para fatos geradores ocorridos exclusivamente no estado do Rio Grande do Sul.","d":"2024-05-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Notificações","u":"2024-05-15","ds":"Deferido o Requerimento nº 1585/2024.","id":"2431027","law":false,"r":"c"},{"t":"PL","n":"1564","y":"2024","e":"Dispõe sobre medidas emergenciais para atenuar os efeitos da crise decorrente de desastres naturais nos setores de turismo e de cultura do Estado do Rio Grande do Sul.\n\nNOVA EMENTA: Dispõe sobre medidas emergenciais destinadas aos setores de turismo e de cultura do Estado do Rio Grande do Sul.","d":"2024-05-06","o":"approved","s":"Transformado em Norma Jurídica","tr":"Transformação em Norma Jurídica","u":"2024-07-05","ds":"Transformado na Lei Ordinária 14917/2024. DOU 08/07/24 PÁG 01 COL 02.","id":"2431026","law":true,"r":"c"},{"t":"PL","n":"1563","y":"2024","e":"Dispõe sobre a dedução de doações no imposto sobre a renda das doações efetuadas para a assistência às pessoas afetadas e a recuperação de danos decorrentes das enchentes no estado do Rio Grande do Sul em 2024.","d":"2024-05-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Notificações","u":"2024-05-15","ds":"Deferido o Requerimento nº 1588/2024.","id":"2431025","law":false,"r":"c"},{"t":"PL","n":"1551","y":"2024","e":"Dispõe sobre a destinação de 50% do Fundo Especial de Financiamento de Campanha para a implementação de medidas emergenciais em resposta à calamidade pública decorrente das enchentes no Estado do Rio Grande do Sul.","d":"2024-05-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Apresentação de Requerimento","u":"2024-06-19","ds":"Apresentação do REQ n. 2270/2024 (Requerimento de Inclusão ou Retirada de Assinatura em Proposição de Iniciativa Individual), pelo Deputado Gustavo Gayer (PL/GO) e outros, que \"Requer a inclusão de coautoria ao Projeto de Lei n.º 1551/2024, que dispõe sobre a destinação de 50% do Fundo Especial de Financiamento de Campanha para a implementação de medidas emergenciais em resposta à calamidade públi","id":"2430967","law":false,"r":"c"},{"t":"PL","n":"1116","y":"2024","e":"Altera a Lei nº 1.579, de 18 de março de 1952, que dispõe sobre as Comissões Parlamentares de Inquérito, para possibilitar o acompanhamento das providências adotadas após o encerramento dos trabalhos.","d":"2024-04-08","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-07-08","ds":"Parecer com Complementação de Voto, Dep. Chris Tonietto (PL-RJ), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação, com substitutivo.","id":"2424865","law":false,"r":"c"},{"t":"PL","n":"997","y":"2024","e":"Altera a Lei 7.102 de 20 de junho de 1983 para dispor sobre os armamentos disponíveis para os vigilantes e dá outras providências.","d":"2024-03-26","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2024-04-09","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 10/04/2024.","id":"2423750","law":false,"r":"m"},{"t":"PDL","n":"30","y":"2024","e":"Susta, parcialmente, a Resolução 23.732 de 27 de fevereiro de 2024 do Tribunal Superior Eleitoral, que dispõe sobre propaganda eleitoral, utilização e geração do horário gratuito e condutas ilícitas em campanha eleitoral, especificamente os artigos 9º-D, 9º-E, 9º-F e 9ª-H incluídos pelo art. 1º da Resolução.","d":"2024-03-05","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-21","ds":"Recebimento pela CCJC, apensado ao PDL-25/2024","id":"2419264","law":false,"r":"c"},{"t":"PDL","n":"24","y":"2024","e":"Este Decreto Legislativo susta os efeitos da Nota Técnica Conjunta n° 2/2024-SAPS/SAES/MS.","d":"2024-02-29","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-04-19","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 20/04/2024.","id":"2419066","law":false,"r":"c"},{"t":"PL","n":"214","y":"2024","e":"Institui o Dia Nacional dos Presos Políticos.","d":"2024-02-07","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-02-26","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 27/02/2024 PAG 130","id":"2417644","law":false,"r":"m"},{"t":"PL","n":"6128","y":"2023","e":"Altera a Lei nº 9.503 de 23 de setembro de 1997, que institui o Código de Trânsito Brasileiro, para exigir a instalação de sistema de alarme com sensor interno de som e movimento nos veículos especialmente destinados à condução coletiva de escolares.","d":"2023-12-20","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Encerramento de Prazo","u":"2025-03-27","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 19/12/2024 a 27/03/2025). Não foram apresentadas emendas.","id":"2415614","law":false,"r":"m"},{"t":"PL","n":"5614","y":"2023","e":"Altera a Lei nº 1.079 de 10 de abril de 1950, para tornar crime de responsabilidade contra a segurança interna o descumprimento de lei que estabelece o efetivo mínimo das Forças de Segurança Pública.","d":"2023-11-21","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apresentação de Requerimento","u":"2026-03-13","ds":"Apresentação do REQ n. 1410/2026 (Requerimento de Desapensação), pelo Deputado Coronel Meira (PL/PE), que \"Requer a desapensação do Projeto de Lei nº 5.614, de 2023, que “torna crime de responsabilidade contra a segurança interna o descumprimento de lei que estabelece o efetivo mínimo das Forças de Segurança Pública”, em relação ao Projeto de Lei nº 1.100, de 2015\".","id":"2405248","law":false,"r":"m"},{"t":"PEC","n":"62","y":"2023","e":"Altera o artigo 122 do Ato das Disposições Constitucionais Transitórias.","d":"2023-11-21","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2023-11-27","ds":"Apresentação do REQ n. 4064/2023 (Requerimento), pela Deputada Gleisi Hoffmann (PT/PR -Fdr PT-PCdoB-PV), que \"Requer a inclusão de coautoria na PEC 62/2023\".","id":"2404706","law":false,"r":"c"},{"t":"PEC","n":"57","y":"2023","e":"Altera os arts. 40 e 144 da Constituição Federal para dispor sobre as Polícias Municipais.","d":"2023-11-08","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-04-06","ds":"O Relator, Dep. Felipe Francischini, deixou de ser membro da Comissão","id":"2402861","law":false,"r":"c"},{"t":"PDL","n":"392","y":"2023","e":"Susta o Decreto nº 11.764, de 31 de outubro de 2023, que altera a Tabela de Incidência do Imposto sobre Produtos Industrializados - TIPI, aprovada pelo Decreto nº 11.158, de 29 de julho de 2022.","d":"2023-11-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-11-07","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 08/11/2023.","id":"2401109","law":false,"r":"c"},{"t":"PL","n":"5021","y":"2023","e":"Institui a Lista de Organizações Terroristas, altera a Lei nº 13.260, de 16 de março de 2016, e dá outras providências.","d":"2023-10-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-07-07","ds":"Apensação da proposição PL 2730/2026 à proposição PL 972/2024.","id":"2396351","law":false,"r":"c"},{"t":"PDL","n":"349","y":"2023","e":"Susta o Decreto nº 11.695, de 11 de setembro de 2023, que promulga o Acordo de Cooperação Técnica entre o Governo da República Federativa do Brasil e a Organização para a Libertação da Palestina, em nome da Autoridade Nacional Palestina, firmado em Ramallah, em 17 de março de 2010.","d":"2023-10-10","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-11-09","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 10/11/2023.","id":"2395550","law":false,"r":"m"},{"t":"PL","n":"4789","y":"2023","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal, a Lei nº 8.069, de 13 de julho de 1990 - Estatuto da Criança e do Adolescente, a Lei nº 8.072, de 25 de julho de 1990 - Lei de Crimes Hediondos, a Lei nº 7.210, de 11 de julho de 1984 - Lei de Execução Penal, e o Decreto Lei nº 3.689, de 3 de outubro de 1941 - Código de Processo Penal, para recrudescer o tratamento penal destinado aos crimes sexuais contra crianças e adolescentes, visando prevenir e coibir o incentivo à pedofilia.","d":"2023-10-03","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-05-21","ds":"Parecer do Relator, Dep. Filipe Martins (PL-TO), pela aprovação do PL 4789/23, do PLs 20/24,1978/24, 3920/25, 4061/25, e 1201/26, apensados, com substitutivo.","id":"2392485","law":false,"r":"m"},{"t":"PDL","n":"337","y":"2023","e":"Susta a Resolução n° 2, de 19 de setembro de 2023, do Conselho Nacional dos Direitos das Pessoas Lésbicas, Gays, Bissexuais, Travestis, Trans., Queers, Intersexos.","d":"2023-09-25","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-07-30","ds":"Designado Relator, Dep. Daniel José (PODE-SP), para o PDL 335/2023, ao qual esta proposição está apensada.","id":"2390075","law":false,"r":"c"},{"t":"PEC","n":"44","y":"2023","e":"Adiciona-se parágrafo 9ºB ao artigo 166 da Constituição Federal para permitir o emendamento em reserva, de 5% para o uso em catástrofes e emergências naturais.\n\n\n\n\nNOVA EMENTA: Altera o art. 166 da Constituição Federal e acrescenta o art. 138 no Ato das Disposições Constitucionais Transitórias, para destinar parte dos recursos das emendas individuais e de bancadas estaduais e do orçamento da União a ações de prevenção, mitigação, preparação, resposta e recuperação de desastres.","d":"2023-09-14","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2024-07-16","ds":"Remessa ao Senado Federal por meio do Of. nº 115/2024/SGM-P.","id":"2388029","law":false,"r":"c"},{"t":"PL","n":"4370","y":"2023","e":"Aumenta a pena do esbulho possessório e estabelece o crime de ocupação como uma forma qualificada desse delito.","d":"2023-09-06","o":"status_not_published","s":"","tr":"Aprovação de Urgência (154, 155 ou 64 CF)","u":"2025-07-16","ds":"Alteração do Regime de Tramitação desta proposição em virtude da alteração do regime do PL 8262/2017, por ter sido aprovado o REQ 4248/2023 que está apensado ao primeiro.","id":"2386359","law":false,"r":"c"},{"t":"PL","n":"4303","y":"2023","e":"Inclui os oficiais de justiça, agentes de trânsito e guardas municipais na qualificadora do crime de homicídio cometido contra integrantes de órgãos de segurança pública.","d":"2023-09-05","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-08-12","ds":"Designado Relator, Dep. Sanderson (PL-RS), para o PL 2530/2015, ao qual esta proposição está apensada.","id":"2385614","law":false,"r":"m"},{"t":"PL","n":"4183","y":"2023","e":"Dispõe sobre a aquisição de personalidade jurídica para o regular funcionamento dos movimentos sociais e populares.","d":"2023-08-29","o":"in_progress","s":"Aguardando Deliberação de Recurso","tr":"Encerramento de Prazo","u":"2024-12-04","ds":"Encerramento automático do Prazo de Recurso 04/12/2024 22:41:00. Foram apresentados 2 recursos.","id":"2383411","law":false,"r":"c"},{"t":"PEC","n":"34","y":"2023","e":"Inclui dispositivos nos artigos 3º e 5º da Constituição da República Federativa do Brasil, estabelecendo o combate às drogas ilícitas como princípio fundamental e vedando expressamente a descriminalização do tráfico e a legalização de novas drogas recreativas.","d":"2023-08-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-02-10","ds":"(Instalação da Comissão) A Relatora, Dep. Caroline de Toni, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2377463","law":false,"r":"c"},{"t":"PL","n":"3763","y":"2023","e":"Dispõe sobre a criação de Delegacias Especializadas em Conflitos Agrários.","d":"2023-08-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2024-12-11","ds":"Encaminhada à publicação. Parecer da Comissão de Segurança Pública e Combate ao Crime Organizado Publicado em avulso e no DCD de 12/12/2024 PÁG 1907, Letra B.","id":"2376039","law":false,"r":"c"},{"t":"PDL","n":"209","y":"2023","e":"Susta os efeitos da Resolução nº 510, de 26 de junho de 2023, do Conselho Nacional de Justiça, que “regulamenta a criação, no âmbito do Conselho Nacional de Justiça e dos Tribunais, respectivamente, da Comissão Nacional de Soluções Fundiárias e das Comissões Regionais de Soluções Fundiárias, institui diretrizes para a realização de visitas técnicas nas áreas objeto de litígio possessório e estabelece protocolos para o tratamento das ações que envolvam despejos ou reintegrações de posse em imóveis de moradia coletiva ou de área produtiva de populações vulneráveis”.","d":"2023-08-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-14","ds":"Recebimento pela CCJC, apensado ao PDL-182/2023","id":"2375447","law":false,"r":"c"},{"t":"PDL","n":"204","y":"2023","e":"Susta parte dos efeitos do DECRETO Nº 6.286, DE 5 DE DEZEMBRO DE 2007, que institui o Programa Saúde na Escola - PSE, e dá outras providências.","d":"2023-08-01","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-11-05","ds":"Parecer da Relatora, Dep. Ana Paula Lima (PT-SC), pela rejeição.","id":"2374905","law":false,"r":"c"},{"t":"PDL","n":"198","y":"2023","e":"Susta os efeitos da Resolução nº 715, de 20 de julho de 2023, do Conselho Nacional de Saúde, que trata das “orientações estratégicas para o Plano Plurianual (PPA) e para o Plano Nacional de Saúde (PNS) 2024-2027”.","d":"2023-07-28","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-28","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 29/09/2023.","id":"2374503","law":false,"r":"c"},{"t":"PDL","n":"195","y":"2023","e":"Susta o Decreto nº 11.615, de 21 de julho de 2023, que regulamenta a Lei nº 10.826, de 22 de dezembro de 2003, para estabelecer regras e procedimentos relativos à aquisição, ao registro, à posse, ao porte, ao cadastro e à comercialização nacional de armas de fogo, munições e acessórios, disciplinar as atividades de caça excepcional, de caça de subsistência, de tiro desportivo e de colecionamento de armas de fogo, munições e acessórios, disciplinar o funcionamento das entidades de tiro desportivo e dispor sobre a estruturação do Sistema Nacional de Armas – Sinarm.","d":"2023-07-27","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2374429","law":false,"r":"c"},{"t":"PDL","n":"188","y":"2023","e":"Susta o Decreto nº 11.615, 21 de julho de 2023, que Regulamenta a Lei nº 10.826, de 22 de dezembro de 2003, para estabelecer regras e procedimentos relativos à aquisição, ao registro, à posse, ao porte, ao cadastro e à comercialização nacional de armas de fogo, munições e acessórios, disciplinar as atividades de caça excepcional, de caça de subsistência, de tiro desportivo e de colecionamento de armas de fogo, munições e acessórios, disciplinar o funcionamento das entidades de tiro desportivo e dispor sobre a estruturação do Sistema Nacional de Armas - Sinarm.","d":"2023-07-21","o":"in_progress","s":"Aguardando Definição Encaminhamento","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2374339","law":false,"r":"c"},{"t":"PDL","n":"186","y":"2023","e":"Susta os efeitos do Decreto nº 11.611, de 19 de Julho 2023, que revoga o Decreto nº 10.004, de 5 de setembro de 2019, que institui o Programa Nacional das Escolas Cívico-Militares.","d":"2023-07-21","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-28","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 29/09/2023.","id":"2374328","law":false,"r":"c"},{"t":"PL","n":"3554","y":"2023","e":"Altera a Lei nº 9.503, de 23 de setembro de 1997, que institui o Código de Trânsito Brasileiro, para garantir livre estacionamento e parada aos veículos de oficiais de justiça em diligência.","d":"2023-07-13","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Apresentação de Proposição","u":"2026-03-23","ds":"Remessa ao Senado Federal por meio do Of. nº 149/2026/PS-GSE.","id":"2374018","law":false,"r":"m"},{"t":"PLP","n":"141","y":"2023","e":"Altera o inciso XIV do artigo 22, da Lei Complementar nº 64, de 18 de maio de 1990, para determinar que a sanção de inelegibilidade para as eleições a se realizarem seja nos 2 (dois) anos subsequentes à eleição.","d":"2023-07-04","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-06-11","ds":"Deferido o REQ 678/2025.","id":"2372482","law":false,"r":"c"},{"t":"PL","n":"3127","y":"2023","e":"Estabelece a vedação à indicação de Ministros de Estado em cargos de representação que auferem remuneração, gratificações de presença ou verbas de representação, para participação em Conselhos de Administração e Fiscal, ou em órgãos equivalentes, de pessoas jurídicas sob controle direto ou indireto da União.","d":"2023-06-16","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2026-05-26","ds":"Devolvida pelo Relator sem Manifestação.","id":"2369984","law":false,"r":"m"},{"t":"PL","n":"2501","y":"2023","e":"Dispõe sobre a criação do crime de censura e confisco de plataforma na lei 13.869 de 5 de setembro de 2019, que dispõe sobre os crimes de abuso de autoridade, e adiciona o crime de censura na lei 1.079 de 10 de abril de 1950, que dispõe sobre os crimes de responsabilidade, e dá outras providências.","d":"2023-05-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-10-15","ds":"Designado Relator, Dep. Pr. Marco Feliciano (PL-SP), para o PL 2782/2022, ao qual esta proposição está apensada.","id":"2361794","law":false,"r":"c"},{"t":"PL","n":"2162","y":"2023","e":"Concede anistia aos participantes das manifestações reivindicatórias de motivação política ocorridas entre o dia 30 de outubro de 2022 e o dia de entrada em vigor desta Lei, e dá outras providências.","d":"2023-04-26","o":"approved","s":"Transformado em Norma Jurídica","tr":"Apresentação de Requerimento","u":"2026-05-08","ds":"Apresentação do REQ n. 2732/2026 (Requerimento de Constituição de Comissão Externa), pelo Deputado Nikolas Ferreira (PL/MG), que \"Requer a criação de Comissão Externa, sem ônus para a Câmara dos Deputados, destinada a acompanhar a aplicação das alterações normativas decorrentes da derrubada de veto ao Projeto de Lei nº 2.162, de 2023, especialmente quanto aos recálculos de pena relativos ao concur","id":"2358548","law":true,"r":"c"},{"t":"PL","n":"1881","y":"2023","e":"Estabelece que a cobrança, pela União, de tarifas, taxas e dos custos operacionais e de manutenção de obras ou serviços públicos vinculados ao aproveitamento econômico e social dos rios e das massas de água, nas regiões de secas periódicas, respeitará o prazo de carência de 5 (cinco) anos da entrada em operação do empreendimento, e altera a Lei nº 14.182, de 12 de julho de 2021, que dispõe sobre a desestatização da empresa Centrais Elétricas Brasileiras S.A. (Eletrobras).","d":"2023-04-13","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-04-17","ds":"Prazo de Vista Encerrado","id":"2356291","law":false,"r":"m"},{"t":"PL","n":"1687","y":"2023","e":"Acrescenta o inciso X, ao §2º do art. 121, do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para tipificar como qualificado o homicídio cometido em estabelecimentos de ensino, templos religiosos, hospitais, asilos ou locais, públicos ou privados, de grande aglomeração de pessoas, com a finalidade de provocar terror social ou generalizado, e altera a Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos).","d":"2023-04-06","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2023-08-30","ds":"Apense-se a este(a) o(a) PL-1880/2023.","id":"2355152","law":false,"r":"m"},{"t":"PL","n":"1340","y":"2023","e":"Altera a Lei nº 11.343, de 23 de agosto de 2006, para condicionar a destinação de recursos para políticas de redução de danos à existência de estudo, monitoramento e relatório de resultados com a anotação de responsabilidade técnica.","d":"2023-03-22","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2024-05-15","ds":"Encaminhada à publicação. Parecer da Comissão de Segurança Pública e Combate ao Crime Organizado Publicado em avulso e no DCD de 16/05/2024, Letra A.","id":"2352542","law":false,"r":"m"},{"t":"PL","n":"1264","y":"2023","e":"Estabelece a equiparação salarial entre servidores das forças de segurança pública que ocupam os mesmos postos, graduações e classes funcionais, dentro de um mesmo ente federativo.","d":"2023-03-21","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-05-12","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 13/05/2023 PAG 74","id":"2352069","law":false,"r":"m"},{"t":"PEC","n":"7","y":"2023","e":"Altera o art. 84, XII, da Constituição Federal de 1988, para estabelecer parâmetro para a concessão de indulto e comutação de penas pelo Presidente da República.","d":"2023-03-16","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Notificação de Despacho","u":"2023-04-27","ds":"Indeferido o REQ 776/2023.","id":"2351680","law":false,"r":"c"},{"t":"PEC","n":"6","y":"2023","e":"Dispõe sobre a autorização prévia pelo Congresso Nacional para operações de crédito de instituições financeiras oficiais federais  ou da República Federativa do Brasil que tenham por objeto a concessão de crédito a outros países ou suas sociedades estatais.","d":"2023-03-16","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-03-31","ds":"Recebimento pela CCJC, apensada à PEC-3/2023","id":"2351620","law":false,"r":"c"},{"t":"PL","n":"1184","y":"2023","e":"Altera o art. 64 da Lei nº 7.210, de 11 de julho de 1984, Lei Execução Penal, para incluir, entre os integrantes do Conselho Nacional de Política Criminal e Penitenciária, membros dos órgãos de segurança pública e representantes do Poder Legislativo Federal.","d":"2023-03-15","o":"in_progress","s":"Aguardando Deliberação de Recurso","tr":"Apresentação de Recurso","u":"2023-05-17","ds":"Apresentação do REC n. 7/2023 (Recurso), pelo Deputado Coronel Meira (PL/PE), que \"Recorre, na forma do § 2ª do art. 137 do Regimento Interno da Câmara dos Deputados, da decisão da Mesa Diretora que negou seguimento à tramitação legislativa do Projeto de Lei nº 1.184, de 2023\".","id":"2351559","law":false,"r":"m"},{"t":"PEC","n":"5","y":"2023","e":"Acrescenta § 4º-A ao art. 150 da Constituição Federal, para dispor sobre a imunidade tributária de que tratam as suas alíneas “b” e “c” do inciso VI.","d":"2023-03-15","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2026-06-01","ds":"Remessa ao Senado Federal por meio do Of. nº 143/2026/SGM-P.","id":"2351506","law":false,"r":"c"},{"t":"PL","n":"1008","y":"2023","e":"Acrescenta o artigo 24-K ao Decreto-Lei nº 667/1969, para determinar o emprego de, no mínimo, 03 (três) militares por viatura, na realização de rondas, operações e patrulhamentos.","d":"2023-03-08","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-08-30","ds":"Recebimento pela CCJC, apensado ao PL-249/2023","id":"2350567","law":false,"r":"m"},{"t":"PL","n":"897","y":"2023","e":"Altera a Lei nº 12.587, de 3 de janeiro de 2012, para incluir a hipótese de autorização para prestação de serviço de transporte remunerado privado individual de passageiros aos motoristas que possuem habilitação na Categoria A.","d":"2023-03-06","o":"status_not_published","s":"","tr":"Notificações","u":"2026-06-10","ds":"Designado Relator, Dep. Zé Trovão (PL-SC), para o PL 271/2023, ao qual esta proposição está apensada.","id":"2350199","law":false,"r":"m"},{"t":"PL","n":"881","y":"2023","e":"Define incentivos fiscais destinados aos projetos sociais e cultura, e altera a Lei nº 8.313, de 23 de dezembro de 1991, Lei de Incentivo à Cultura (Lei Rouanet), a fim de destinar parte dos valores aportados para projetos culturais para o financiamento de projetos de valorização e apoio às Comunidades Tradicionais e Indígenas.","d":"2023-03-06","o":"status_not_published","s":"","tr":"Notificações","u":"2026-02-24","ds":"Designado Relator, Dep. Alfredinho (PT-SP), para o PL 5721/2016, ao qual esta proposição está apensada.","id":"2350089","law":false,"r":"m"},{"t":"PDL","n":"24","y":"2023","e":"Susta a INSTRUÇÃO NORMATIVA SEGES/MGI n°4, de 2 de fevereiro de 2023, que flexibiliza e estabelece regras complementares para a hipótese de bens passíveis de serem adquiridos com características superiores para estrita atividade do órgão ou entidade pública.","d":"2023-02-07","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-03-23","ds":"Parecer do Relator, Dep. Capitão Alden (PL-BA), pela aprovação deste, na forma do substitutivo, e do PDL 49/2023, apensado.","id":"2347130","law":false,"r":"m"}];
